    correction: [{"quoi":"القاعدة","math":"نرتّب القيم تصاعديا ; إذا كان N فرديا فالموسّط هو القيمة ذات الرتبة <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">N+1</span><span class=\"den\">2</span></span></span>، و إذا كان زوجيا فهو معدّل القيمتين ذواتي الرتبتين <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">N</span><span class=\"den\">2</span></span></span> و <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">N</span><span class=\"den\">2</span></span> + 1</span>"},{"quoi":"نحسب التكرار الجملي","math":"<span dir=\"ltr\" class=\"expr\">N = 30</span>"},{"quoi":"و هو زوجي","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">N</span><span class=\"den\">2</span></span> = 15</span>"},{"quoi":"نكوّن التكرارات المتراكمة الصاعدة","math":"<span dir=\"ltr\" class=\"expr\">ca = 2</span>"},{"quoi":"و نواصل إلى","math":"<span dir=\"ltr\" class=\"expr\">cf = 30</span>"},{"quoi":"نقرأ القيمة ذات الرتبة <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">N</span><span class=\"den\">2</span></span></span>","math":"الرتبة 15 تقابل القيمة 7"},{"quoi":"و القيمة ذات الرتبة <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">N</span><span class=\"den\">2</span></span> + 1</span>","math":"الرتبة 16 تقابل القيمة 7"},{"quoi":"النتيجة","math":"الموسّط يساوي <span dir=\"ltr\" class=\"expr\">Me = 7</span>"}],
