    correction: [{"quoi":"القاعدة","math":"نرتّب القيم تصاعديا ; إذا كان N فرديا فالموسّط هو القيمة ذات الرتبة <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">N+1</span><span class=\"den\">2</span></span></span>، و إذا كان زوجيا فهو معدّل القيمتين ذواتي الرتبتين <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">N</span><span class=\"den\">2</span></span></span> و <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">N</span><span class=\"den\">2</span></span> + 1</span>"},{"quoi":"نحسب التكرار الجملي","math":"<span dir=\"ltr\" class=\"expr\">N = 49</span>"},{"quoi":"و هو فردي","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">N + 1</span><span class=\"den\">2</span></span> = 25</span>"},{"quoi":"نكوّن التكرارات المتراكمة الصاعدة","math":"<span dir=\"ltr\" class=\"expr\">ca = 10</span>"},{"quoi":"و نواصل إلى","math":"<span dir=\"ltr\" class=\"expr\">cf = 49</span>"},{"quoi":"نقرأ القيمة ذات الرتبة <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">N+1</span><span class=\"den\">2</span></span></span>","math":"الرتبة 25 تقابل القيمة 2"},{"quoi":"و هي وحدها","math":"لا حاجة إلى رتبة ثانية"},{"quoi":"النتيجة","math":"الموسّط يساوي <span dir=\"ltr\" class=\"expr\">Me = 2</span>"}],
